import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Google Antigravity","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/gemini/antigravity.md","filePath":"products/ai-coding/gemini/antigravity.md","lastUpdated":1787044708000}'),i={name:"products/ai-coding/gemini/antigravity.md"};function n(r,e,l,d,h,c){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="google-antigravity" tabindex="-1">Google Antigravity <a class="header-anchor" href="#google-antigravity" aria-label="Permalink to &quot;Google Antigravity&quot;">​</a></h1><blockquote><p>Google&#39;s agent-first development platform. It is not &quot;an editor with AI bolted on&quot; — the unit of interaction is <strong>one task</strong>, not one keystroke.</p><p><strong>Since 2026-06-18</strong> this (including the CLI surface) is the daily entry point for individual / Google AI Pro / Ultra accounts, replacing Gemini CLI <strong>Login with Google</strong>. <a href="https://developers.googleblog.com/an-important-update-transitioning-gemini-cli-to-antigravity-cli" target="_blank" rel="noreferrer">Transition announcement</a>.</p></blockquote><h2 id="what-it-is-for" tabindex="-1">What it is for <a class="header-anchor" href="#what-it-is-for" aria-label="Permalink to &quot;What it is for&quot;">​</a></h2><p>Antigravity assumes the AI can plan on its own, call tools and execute multi-step work. That premise changes what you have to feed it: a completion tool needs a cursor position, Antigravity needs a goal, constraints and acceptance criteria.</p><p>Three things decide how far its capability reaches:</p><table tabindex="0"><thead><tr><th>What you provide</th><th>Carrier</th><th>Effect</th></tr></thead><tbody><tr><td>Long-lived invariants</td><td><a href="#rules">Rules</a></td><td>&quot;this project must be done this way&quot;</td></tr><tr><td>Reusable procedures</td><td><a href="#skills">Skills</a> and <a href="#workflows">Workflows</a></td><td>&quot;for this kind of work, follow this playbook&quot;</td></tr><tr><td>The outside world</td><td>MCP</td><td>lets it query GitHub, drive a browser</td></tr></tbody></table><h2 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h2><p>The official docs describe Antigravity as several surfaces built on <strong>the same agent harness</strong>:</p><table tabindex="0"><thead><tr><th>Surface</th><th>Shape</th><th>Suits</th></tr></thead><tbody><tr><td>Desktop app</td><td>GUI</td><td>interactive exploration, verifying as you go</td></tr><tr><td>CLI</td><td>Terminal UI</td><td>slotting into existing scripts and terminal workflows</td></tr><tr><td>SDK</td><td>Python</td><td>embedding the agent in your own automation</td></tr><tr><td>IDE integration</td><td>Inside the editor</td><td>staying in the editor you already use</td></tr></tbody></table><p><strong>This is the most practical thing to know</strong>: because they share one harness, rules and skills are <strong>effective across surfaces</strong>. You do not configure them twice for desktop and CLI, and you do not learn a second mental model — pick whichever entry point fits how you are working right now.</p><p>On models, the official model documentation notes that Gemini 3.5 Flash powers all of Antigravity&#39;s local agents. There is also a hosted form, <code>antigravity-preview-05-2026</code>, which the docs describe as a general-purpose hosted agent that plans autonomously, executes code, manages files and browses the web inside an isolated Linux sandbox.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>Rules are long-lived behavioural constraints, at two levels:</p><table tabindex="0"><thead><tr><th>Level</th><th>Location</th><th>Scope</th></tr></thead><tbody><tr><td>Global</td><td><code>~/.gemini/GEMINI.md</code></td><td>all workspaces</td></tr><tr><td>Workspace</td><td><code>.agents/rules</code> directory</td><td>travels with the repo, committable</td></tr></tbody></table><p><strong>The docs state a hard limit of 12,000 characters per rule file.</strong> When you reach it, split the file and cross-reference with <code>@filename</code> rather than squeezing the wording to fit.</p><h3 id="four-activation-modes" tabindex="-1">Four activation modes <a class="header-anchor" href="#four-activation-modes" aria-label="Permalink to &quot;Four activation modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>When it loads</th><th>Suits</th></tr></thead><tbody><tr><td>Manual</td><td>when you reference it by hand</td><td>conventions needed only occasionally</td></tr><tr><td>Always On</td><td>every time</td><td>genuinely global iron laws</td></tr><tr><td>Model Decision</td><td>when the model judges it relevant</td><td>situational advice</td></tr><tr><td>Glob</td><td>when a file pattern matches</td><td>stack-specific conventions</td></tr></tbody></table><p><strong>Prefer Glob.</strong> &quot;React component conventions&quot; loading only for <code>src/**/*.tsx</code> is far cheaper than Always On sitting in context permanently. Always On should be reserved for the very few real invariants.</p><h3 id="what-belongs-in-a-rule" tabindex="-1">What belongs in a rule <a class="header-anchor" href="#what-belongs-in-a-rule" aria-label="Permalink to &quot;What belongs in a rule&quot;">​</a></h3><p>Only the few things <strong>the agent actually gets wrong</strong>:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Project constraints</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pnpm only; npm install / yarn add must never appear</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> every new component needs explicit Props types, no any</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> src/legacy/ is read-only; ask before changing anything there</span></span></code></pre></div><p>Do not paste your whole coding standard in. It already knows to write semicolons.</p><blockquote><p>⚠️ The rules file is <strong>not</strong> an <code>agents.md</code> at the project root. That form appeared in older docs and is wrong. The paths are <code>~/.gemini/GEMINI.md</code> (global) and the <code>.agents/rules</code> directory (workspace).</p></blockquote><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>A skill is <strong>a directory</strong> containing a <code>SKILL.md</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.agents/skills/release-flow/          # travels with the repo</span></span>
<span class="line"><span>└── SKILL.md</span></span>
<span class="line"><span></span></span>
<span class="line"><span>~/.gemini/config/skills/release-flow/ # global</span></span>
<span class="line"><span>└── SKILL.md</span></span></code></pre></div><p>In the frontmatter, <code>description</code> is required and <code>name</code> is optional:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Use when a release needs cutting for this project; covers version bump, changelog and tag end to end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Release process</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Confirm CI is green on main</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Update CHANGELOG.md</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ...</span></span></code></pre></div><p><strong><code>description</code> decides whether the skill gets used at all</strong>, so write it as a trigger condition (&quot;when a release needs cutting…&quot;), not as a title (&quot;release process&quot;). The model reads it to judge whether the current task matches.</p><p><strong>Because a skill is a directory</strong>, you can put scripts, templates and sample data alongside it and have <code>SKILL.md</code> reference them — that is the biggest difference from a single prompt file.</p><blockquote><p>⚠️ A flat <code>.agents/skills/xxx.md</code> is not recognised as a skill. <code>.agent/skills</code> (singular) is kept only for backward compatibility; use <code>.agents/skills</code> for anything new.</p></blockquote><h2 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h2><p>Workflows are invoked explicitly as <code>/&lt;workflow-name&gt;</code>.</p><p><strong>How they differ from skills</strong>: who holds the trigger.</p><ul><li>Skill: the model reads <code>description</code> and decides whether to use it</li><li>Workflow: you decide when it runs</li></ul><p>Write a skill when you want automatic matching, a workflow when you want to pick the moment. Pre-release checks and weekly report generation — procedures that must be started by a human — belong to the latter.</p><h2 id="subagents-and-artifacts" tabindex="-1">Subagents and artifacts <a class="header-anchor" href="#subagents-and-artifacts" aria-label="Permalink to &quot;Subagents and artifacts&quot;">​</a></h2><p>These two mechanisms are how Antigravity handles large tasks, and they are the line between it and &quot;a smarter completion tool&quot;.</p><p><strong>Asynchronous subagents</strong>: the main agent dispatches subordinate agents to work in parallel. The value is context economy — each subagent reads one module and returns a conclusion, so the main agent consumes conclusions rather than raw files and the same window covers a much bigger task.</p><p><strong>Artifacts</strong>: reviewable intermediate products the agent emits, such as a plan, a task list or a verification record. They are the brake that comes with autonomy: the more autonomous the agent, the less transparent &quot;what is it actually about to do&quot; becomes, and artifacts turn that black-box middle state into something you can read and veto.</p><h2 id="a-typical-workflow-cross-module-refactor" tabindex="-1">A typical workflow: cross-module refactor <a class="header-anchor" href="#a-typical-workflow-cross-module-refactor" aria-label="Permalink to &quot;A typical workflow: cross-module refactor&quot;">​</a></h2><p>This is where Antigravity&#39;s advantage over other tools is clearest, because the two mechanisms above map onto exactly this risk.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Describe the goal and acceptance criteria, have it emit a plan artifact</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>2. Read the plan, veto the parts pointing the wrong way   ← the human checkpoint</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>3. Let it execute (subagents can read several modules in parallel)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>4. Use its verification record to decide how much to trust, then review the key changes yourself</span></span></code></pre></div><p><strong>Make sure the workspace is clean before you start.</strong> Concurrency means changes arrive from several directions, and afterwards you cannot tell which came from where.</p><h2 id="common-problems" tabindex="-1">Common problems <a class="header-anchor" href="#common-problems" aria-label="Permalink to &quot;Common problems&quot;">​</a></h2><p><strong>A rule is written but it is not being followed</strong>: check the activation mode first. Manual rules do not load automatically; for Glob, confirm the file you are editing actually matches the pattern.</p><p><strong>A skill never triggers</strong>: <code>description</code> was written as a title instead of a trigger condition. Rewrite it as &quot;when …&quot;.</p><p><strong>Context fills up fast</strong>: too many Always On rules. Move the stack-specific ones to Glob.</p><h2 id="choosing-between-this-and-the-others" tabindex="-1">Choosing between this and the others <a class="header-anchor" href="#choosing-between-this-and-the-others" aria-label="Permalink to &quot;Choosing between this and the others&quot;">​</a></h2><p>The full comparison of Antigravity (local, you converse in real time) vs Code Assist (in-IDE, editor-triggered) vs Jules (cloud, asynchronous, produces a PR) is in the <a href="./gemini-cheatsheet.html#antigravity-vs-code-assist-vs-jules">cheatsheet</a> and is not repeated here.</p><p>The one-line version: <strong>big local changes you want to verify as they happen go to Antigravity, work you hand off and collect as a PR goes to <a href="./jules.html">Jules</a>, small in-editor changes go to <a href="./code-assist.html">Code Assist</a>.</strong></p><h2 id="official-resources" tabindex="-1">Official resources <a class="header-anchor" href="#official-resources" aria-label="Permalink to &quot;Official resources&quot;">​</a></h2><ul><li><a href="https://antigravity.google/docs/home" target="_blank" rel="noreferrer">Antigravity docs home</a></li><li><a href="https://antigravity.google/docs/rules-workflows" target="_blank" rel="noreferrer">Rules &amp; Workflows</a></li><li><a href="https://antigravity.google/docs/skills" target="_blank" rel="noreferrer">Skills</a></li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./gemini-cheatsheet.html">Cheatsheet</a> — rule/skill paths, cross-product decision table</li><li><a href="./gemini-glossary.html">Glossary</a> — definitions of Surface, Rules, Skill, Subagent, Artifact</li><li><a href="./gemini-cookbook.html#_11-cross-module-refactor-that-needs-verification-as-it-goes">Cookbook</a> — the cross-module refactor recipe</li></ul>`,55)])])}const f=t(i,[["render",n]]);export{k as __pageData,f as default};
